def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents
    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append(opp)

    # If no opponents alive, bid conservatively
    if not alive:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday's bids from previous_trace
    yesterday_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', None) or {}
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many water units are likely needed to survive the day
    # (We only use it to scale our bid aggressiveness.)
    # With supply range 15-25 and WATER_REQ=13, typically 1 unit is enough; sometimes 2 if supply>26 (not here).
    # So treat as single-unit competition.
    likely_units = 1

    my_hp = float(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Base bid: aim around a fraction of daily salary to stay competitive but not reckless.
    # If I'm low hp or have been without water, increase urgency.
    if my_hp <= 2 or no_water_days >= 1:
        base = DAILY_SALARY * 0.85
    elif my_hp <= 4:
        base = DAILY_SALARY * 0.65
    else:
        base = DAILY_SALARY * 0.55

    # React to very high yesterday bids: opponents likely contesting strongly.
    # If someone bid extremely high yesterday, we raise bid but cap it to preserve budget.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Bid slightly above the likely contest threshold, but not more than necessary.
        target = highest_prev_bid + 5.0
        # If my hp is critical, be more aggressive.
        if my_hp <= 2:
            target = max(target, DAILY_SALARY * 0.95)
        else:
            target = max(target, DAILY_SALARY * 0.70)
        bid = min(my_budget, target)
    else:
        # If contest wasn't extreme, bid near base; also nudge upward if my supply is near minimum.
        # Lower supply => higher competition => bid a bit more.
        supply_factor = 1.0
        if supply <= float(MIN_SUPPLY) + 0.5:
            supply_factor = 1.12
        elif supply >= float(MAX_SUPPLY) - 0.5:
            supply_factor = 0.95
        bid = min(my_budget, base * supply_factor)

    # Ensure bid is at least a small positive amount when we have budget.
    if my_budget > 0:
        bid = max(0.0, float(bid))
    else:
        bid = 0.0

    return float(bid)

