def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if yesterday_bids:
        avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids)
        if avg_opp_bid > DAILY_SALARY:
            return min(my_status['budget'], DAILY_SALARY * 0.4)
        return min(my_status['budget'], avg_opp_bid + 5.0)

    return min(my_status['budget'], DAILY_SALARY * 0.6)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    hp = my_status['hp']
    budget = my_status['budget']
    supply = day_context['supply']
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}

    # Determine highest previous bid among alive opponents
    highest_prev_bid = 0.0
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid_val = prev['bid']
            if bid_val > highest_prev_bid:
                highest_prev_bid = bid_val

    # Base bid: moderate if HP is safe, else aggressive
    if hp <= 2:
        # Desperate: bid high to guarantee water
        base_bid = DAILY_SALARY * 0.9
    elif hp <= 4:
        base_bid = DAILY_SALARY * 0.7
    else:
        # HP comfortable, conserve budget
        base_bid = DAILY_SALARY * 0.5

    # Adjust for supply scarcity
    if supply < 20:
        base_bid += DAILY_SALARY * 0.1

    # React to highest opponent's previous bid
    if highest_prev_bid > DAILY_SALARY * 0.85:
        # Opponent was very aggressive yesterday; avoid overbidding unless desperate
        if hp <= 2:
            adjusted = max(base_bid, highest_prev_bid + 1)
        else:
            adjusted = min(base_bid, DAILY_SALARY * 0.6)
    else:
        # Opponents were moderate; match or slightly exceed
        adjusted = max(base_bid, highest_prev_bid + 2)

    # Ensure we don't exceed budget and not negative
    bid = min(budget, adjusted)
    bid = max(0, bid)
    return bid
